var WF_UP = '#EF4444';
var WF_DOWN = '#10B981';
var WF_TOTAL = '#5E6AD2';

function parseSeries(text){
  var lines = String(text == null ? '' : text).split(/\r?\n/);
  var items = [], errors = [];
  for (var i = 0; i < lines.length; i++){
    var l = lines[i].trim();
    if (!l || l.charAt(0) === '#') continue;
    var m = /^(.*?)[\s:：|,，]+([=+\-]?[\d,]*\.?\d*)$/.exec(l);
    if (!m){ errors.push({ line:i + 1, text:l, why:'格式应为 标签 数值 / 标签 =' }); continue; }
    var label = m[1].trim(), raw = m[2].trim();
    if (!label){ errors.push({ line:i + 1, text:l, why:'缺少标签' }); continue; }
    if (raw === '='){ items.push({ label:label, type:'subtotal', value:0 }); continue; }
    var signed = raw.charAt(0) === '+' || raw.charAt(0) === '-';
    var num = parseFloat(raw.replace(/,/g, ''));
    if (!isFinite(num)){ errors.push({ line:i + 1, text:l, why:'数值无法解析' }); continue; }
    if (signed) items.push({ label:label, type:'delta', value:num });
    else if (items.length === 0) items.push({ label:label, type:'start', value:num });
    else items.push({ label:label, type:'absolute', value:num });
  }
  return { items:items, errors:errors };
}

function compute(items){
  var rows = [], running = 0, started = false;
  for (var i = 0; i < items.length; i++){
    var it = items[i];
    if (it.type === 'start'){
      running = it.value; started = true;
      rows.push({ label:it.label, type:'start', delta:it.value, start:0, end:running, cumulative:running });
    } else if (it.type === 'delta'){
      var s = running; running += it.value;
      rows.push({ label:it.label, type:'delta', delta:it.value, start:s, end:running, cumulative:running });
      started = true;
    } else if (it.type === 'absolute'){
      var s2 = running, d = it.value - running; running = it.value;
      rows.push({ label:it.label, type:'absolute', delta:d, start:s2, end:running, cumulative:running });
      started = true;
    } else if (it.type === 'subtotal'){
      rows.push({ label:it.label, type:'subtotal', delta:running, start:0, end:running, cumulative:running });
    }
  }
  return { rows:rows, total:round2(running), started:started };
}

function round2(n){ return Math.round(n * 100) / 100; }

function analyze(rows){
  var up = 0, down = 0, biggestUp = null, biggestDown = null, start = null, end = 0;
  for (var i = 0; i < rows.length; i++){
    var r = rows[i];
    if (r.type === 'start'){ start = r.end; continue; }
    if (r.type === 'subtotal') continue;
    if (r.delta > 0){ up += r.delta; if (!biggestUp || r.delta > biggestUp.delta) biggestUp = r; }
    else if (r.delta < 0){ down += r.delta; if (!biggestDown || r.delta < biggestDown.delta) biggestDown = r; }
  }
  if (rows.length) end = rows[rows.length - 1].cumulative;
  if (start === null) start = 0;
  var net = end - start;
  return {
    start:round2(start), end:round2(end), net:round2(net),
    pct: start !== 0 ? Math.round(net / Math.abs(start) * 1000) / 10 : null,
    gain:round2(up), loss:round2(down),
    biggestUp:biggestUp, biggestDown:biggestDown,
    contributions: rows.filter(function(r){ return r.type === 'delta' || r.type === 'absolute'; })
      .map(function(r){ return { label:r.label, delta:round2(r.delta), share: up - down !== 0 ? Math.round(Math.abs(r.delta) / (up - down) * 1000) / 10 : 0 }; })
      .sort(function(a, b){ return Math.abs(b.delta) - Math.abs(a.delta); })
  };
}

function niceStep(range, target){
  if (!(range > 0)) return 1;
  var raw = range / (target || 5);
  var mag = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10));
  var norm = raw / mag;
  var step = norm <= 1 ? 1 : norm <= 2 ? 2 : norm <= 5 ? 5 : 10;
  return step * mag;
}

function layout(rows, opt){
  opt = opt || {};
  var W = opt.width || 680, H = opt.height || 340;
  var padL = opt.padL || 56, padR = 14, padT = 16, padB = 52;
  if (!rows.length) return { bars:[], width:W, height:H, empty:true, ticks:[] };
  var lo = 0, hi = 0;
  for (var i = 0; i < rows.length; i++){
    lo = Math.min(lo, rows[i].start, rows[i].end);
    hi = Math.max(hi, rows[i].start, rows[i].end);
  }
  if (hi === lo) hi = lo + 1;
  var pad = (hi - lo) * 0.08;
  hi += pad; lo -= pad;
  var plotH = H - padT - padB, plotW = W - padL - padR;
  var y = function(v){ return padT + (hi - v) / (hi - lo) * plotH; };
  var slot = plotW / rows.length, bw = Math.max(6, Math.min(48, slot * 0.62));
  var bars = [];
  for (var j = 0; j < rows.length; j++){
    var r = rows[j];
    var cx = padL + slot * j + slot / 2;
    var yTop = y(Math.max(r.start, r.end)), yBot = y(Math.min(r.start, r.end));
    var color = r.type === 'start' || r.type === 'subtotal' ? WF_TOTAL : (r.delta >= 0 ? WF_UP : WF_DOWN);
    bars.push({ label:r.label, type:r.type, delta:round2(r.delta), cumulative:round2(r.cumulative),
                x:cx - bw / 2, y:yTop, w:bw, h:Math.max(1.5, yBot - yTop), cx:cx, color:color,
                connectorY:y(r.end) });
  }
  var step = niceStep(hi - lo, 5), ticks = [];
  var t0 = Math.ceil(lo / step) * step;
  for (var t = t0; t <= hi + 1e-9; t += step) ticks.push({ value:round2(t), y:y(t) });
  return { bars:bars, ticks:ticks, width:W, height:H, padL:padL, padT:padT, plotW:plotW, plotH:plotH, zeroY:y(0), empty:false };
}

function escXml(s){
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function fmtNum(n){
  var a = Math.abs(n);
  if (a >= 1e8) return (Math.round(n / 1e7) / 10) + '亿';
  if (a >= 1e4) return (Math.round(n / 1e3) / 10) + '万';
  return String(Math.round(n * 100) / 100);
}

function toSvg(lay){
  if (!lay || lay.empty) return '<svg xmlns="http://www.w3.org/2000/svg" width="' + ((lay && lay.width) || 680) + '" height="' + ((lay && lay.height) || 340) + '"></svg>';
  var out = ['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + lay.width + ' ' + lay.height + '" width="100%" height="' + lay.height + '" role="img" aria-label="瀑布图">'];
  out.push('<rect width="' + lay.width + '" height="' + lay.height + '" fill="#0A0A0B"/>');
  for (var t = 0; t < lay.ticks.length; t++){
    var tk = lay.ticks[t];
    out.push('<line x1="' + lay.padL + '" y1="' + r2(tk.y) + '" x2="' + (lay.width - 14) + '" y2="' + r2(tk.y) + '" stroke="rgba(255,255,255,.08)"/>');
    out.push('<text x="' + (lay.padL - 8) + '" y="' + r2(tk.y + 4) + '" fill="#71717A" font-size="10" text-anchor="end" font-family="system-ui,sans-serif">' + escXml(fmtNum(tk.value)) + '</text>');
  }
  for (var i = 0; i < lay.bars.length; i++){
    var b = lay.bars[i];
    if (i > 0){
      var prev = lay.bars[i - 1];
      out.push('<line x1="' + r2(prev.cx + prev.w / 2) + '" y1="' + r2(prev.connectorY) + '" x2="' + r2(b.cx - b.w / 2) + '" y2="' + r2(prev.connectorY) + '" stroke="rgba(255,255,255,.22)" stroke-dasharray="3 3"/>');
    }
    out.push('<rect x="' + r2(b.x) + '" y="' + r2(b.y) + '" width="' + r2(b.w) + '" height="' + r2(b.h) + '" rx="2" fill="' + b.color + '"><title>' + escXml(b.label + ': ' + (b.delta >= 0 && b.type === 'delta' ? '+' : '') + b.delta + ' → ' + b.cumulative) + '</title></rect>');
    out.push('<text x="' + r2(b.cx) + '" y="' + r2(b.y - 5) + '" fill="#FFFFFF" font-size="10" text-anchor="middle" font-family="system-ui,sans-serif">' + escXml((b.type === 'delta' && b.delta > 0 ? '+' : '') + fmtNum(b.delta)) + '</text>');
    out.push('<text x="' + r2(b.cx) + '" y="' + (lay.height - 28) + '" fill="#A1A1AA" font-size="10" text-anchor="middle" font-family="system-ui,sans-serif">' + escXml(b.label) + '</text>');
  }
  out.push('</svg>');
  return out.join('');
}

function r2(n){ return Math.round(n * 100) / 100; }

var WaterfallForgePure = {
  parseSeries: parseSeries, compute: compute, analyze: analyze, layout: layout, toSvg: toSvg,
  niceStep: niceStep, fmtNum: fmtNum, UP: WF_UP, DOWN: WF_DOWN, TOTAL: WF_TOTAL
};
if (typeof module !== 'undefined' && module.exports) module.exports = WaterfallForgePure;
if (typeof window !== 'undefined') window.WaterfallForgePure = WaterfallForgePure;
